def _refresh_slice_bounds() -> None:
    """停點從 ledger 最後一天長出來，新段不必改兩行日期。"""
    global SLICE_STOP, NEXT_START
    last = max(str(e.get("date") or "") for e in _EVENTS)
    SLICE_STOP = last
    NEXT_START = (
        datetime.strptime(last, "%Y-%m-%d") + timedelta(days=1)
    ).strftime("%Y-%m-%d")


_refresh_slice_bounds()

